// --- inputs -----------------------------------------------------------------
let intent = actions.automate_email_intent_int;

// --- read the AI Action, or say why it could not be read ------------------------
// An AI Action response carries no _zt_meta - only Connected Object responses do - so the
// output itself is the signal: every answer this Action returns carries email_intent. A
// response without it never ran, and that must not read as "no intent matched" on screen
// 29 - it goes to the agent instead.
let intentRead = intent.email_intent !== undefined;
let intents = [];
let sentiment = "";
let escalate_reason = "";
let confidence_score = "";
let ai_exception_reason = "The intent check did not return a result. Work this case as you normally would.";

if (intentRead) {
  intents = intent.email_intent;
  sentiment = intent.sentiment;
  escalate_reason = intent.escalate_reason;
  confidence_score = intent.confidence_score;
  ai_exception_reason = intent.ai_exception_reason;
}

// --- transform: one route for the router --------------------------------------
let intentInScope = intents.length > 0 && !intents.includes("other");
let email_analysis_route = "escalation";
if (intentRead && intent.escalate_to_agent !== true) {
  if (intentInScope) {
    email_analysis_route = "in_scope";
  } else {
    email_analysis_route = "out_of_scope";
  }
}

// --- fee layout: Corpay's multi-fee reply layout is only for 2+ of these fees (Gemma Danks, 19 Oct)
const multiFeeIntents = ["ecopoint", "zero_liability", "extended_payment_terms"];
let fee_layout = intents.filter(name => multiFeeIntents.includes(name)).length >= 2 ? "multi_fee" : "standard";
// The approved multi-fee layout, passed to the reply AI Action (15) only when fee_layout is multi_fee.
const multiFeeLayoutLines = [
  "MULTI-FEE LAYOUT (approved by Corpay, Gemma Danks, 19 Oct). This email has two or more of Ecopoint, Zero Liability and Extended Payment Terms. Write those fees as ONE section, in this structure:",
  "  Please see below an explanation of the fees that you have queried:",
  "  <p><u><strong>Zero Liability</strong></u></p> then the zero_liability template text, word for word, WITHOUT its \"Once submitted, requests can take up to 10 working days...\" line",
  "  <p><u><strong>Ecopoint</strong></u></p> then the ecopoint template text, word for word, WITHOUT its \"Once submitted...\" line",
  "  <p><u><strong>Extended Payment Terms</strong></u></p> then the extended_payment_terms template text, word for word, WITHOUT its \"Once submitted...\" line",
  "  (only the fees that are in this email)",
  "  Then this line ONCE, after the last fee: Once submitted for either or both fees, requests can take up to 10 working days to process during which time you will still be liable for any charges as per our terms and conditions.",
  "Never repeat \"Thank you for your email.\" or the \"Once submitted...\" line. Keep every link with its own fee.",
  "If the email has ONLY fee topics, the whole email is: Hello, / Thank you for your email. / [this section] / Kind regards, / Allstar Customer Support"
];
let fee_layout_instructions = fee_layout === "multi_fee" ? multiFeeLayoutLines.join("\n") : "";

// --- outputs ----------------------------------------------------------------
ZT.setFormData("email_intent", intents.join(", "));
ZT.setFormData("fee_layout", fee_layout);
ZT.setFormData("fee_layout_instructions", fee_layout_instructions);
ZT.setFormData("sentiment", sentiment);
ZT.setFormData("escalate_reason", escalate_reason);
ZT.setFormData("confidence_score", confidence_score);
ZT.setFormData("ai_exception_reason", ai_exception_reason);
ZT.setFormData("email_analysis_route", email_analysis_route);
// A new intent read starts with nothing added by the agent (screen 62).
ZT.setFormData("agent_added_request", "");

